settings.markdownTextFunction:
// Top-down room view: 3 radars at 0/120/240 deg, 120 deg fields of view.
var d = (data && data.length) ? data[0] : null;
if (!d) return '<div style="padding:16px;color:#888">Waiting for data...</div>';
function val(k) { var x = d[k]; return (x === undefined || x === null || x === '') ? null : x; }
function num(k) { var x = parseFloat(val(k)); return isNaN(x) ? null : x; }
var W = 320, C = 160, R = 130, MAX = 11;
function r2s(m) { return Math.max(0, Math.min(m, MAX)) / MAX * R; }
function pt(deg, r) { var a = (deg - 90) * Math.PI / 180; return (C + r * Math.cos(a)).toFixed(1) + ',' + (C + r * Math.sin(a)).toFixed(1); }
function wedge(face, r0, r1) {
  var a0 = face - 60, a1 = face + 60;
  var p = 'M' + pt(a0, r0) + ' L' + pt(a0, r1) + ' A' + r1.toFixed(1) + ' ' + r1.toFixed(1) + ' 0 0 1 ' + pt(a1, r1) + ' L' + pt(a1, r0);
  if (r0 > 0) p += ' A' + r0.toFixed(1) + ' ' + r0.toFixed(1) + ' 0 0 0 ' + pt(a0, r0);
  return p + ' Z';
}
var radars = [
  { id: 'r1', name: 'Radar 1', face: 0,   color: '#2196f3' },
  { id: 'r2', name: 'Radar 2', face: 120, color: '#4caf50' },
  { id: 'r3', name: 'Radar 3', face: 240, color: '#ff9800' }
];
var s = '<svg viewBox="0 0 ' + W + ' ' + W + '" width="100%" style="max-height:100%;font-family:Roboto,sans-serif">';
for (var m = 2; m <= 10; m += 2) {
  s += '<circle cx="' + C + '" cy="' + C + '" r="' + r2s(m).toFixed(1) + '" fill="none" stroke="#e0e0e0"/>';
  s += '<text x="' + (C + 3) + '" y="' + (C - r2s(m) + 11).toFixed(1) + '" font-size="9" fill="#9e9e9e">' + m + ' m</text>';
}
var lines = [];
radars.forEach(function (rd) {
  s += '<path d="' + wedge(rd.face, 0, R) + '" fill="' + rd.color + '" fill-opacity="0.07" stroke="' + rd.color + '" stroke-opacity="0.35"/>';
  s += '<text x="' + pt(rd.face, R + 14).split(',')[0] + '" y="' + (parseFloat(pt(rd.face, R + 14).split(',')[1]) + 4) + '" font-size="11" text-anchor="middle" fill="' + rd.color + '" font-weight="600">' + rd.name.replace('Radar ', 'R') + '</text>';
  if (rd.id === 'r3') {
    var det = String(val('r3_detected')) === '1';
    if (det) s += '<path d="' + wedge(rd.face, 0, R) + '" fill="' + rd.color + '" fill-opacity="0.28"/>';
    lines.push(rd.name + ': ' + (det ? 'detected (no distance, OUT pin only)' : 'nothing'));
    return;
  }
  var st = val(rd.id + '_state') || 'none', dist = num(rd.id + '_dist_m');
  if ((st === 'moving' || st === 'still') && dist !== null) {
    if (dist <= MAX) {
      var r = r2s(dist);
      s += '<path d="' + wedge(rd.face, Math.max(0, r - 4), r + 4) + '" fill="' + rd.color + '" fill-opacity="' + (st === 'moving' ? 0.95 : 0.55) + '"/>';
      s += '<text x="' + pt(rd.face, r + 18).split(',')[0] + '" y="' + (parseFloat(pt(rd.face, r + 18).split(',')[1]) + 4) + '" font-size="11" text-anchor="middle" font-weight="600" fill="#212121">' + dist.toFixed(1) + ' m</text>';
      lines.push(rd.name + ': ' + st + ' at ' + dist.toFixed(2) + ' m' + (val(rd.id + '_dir') && val(rd.id + '_dir') !== 'none' ? ', ' + val(rd.id + '_dir') : ''));
    } else {
      lines.push(rd.name + ': ' + st + ', distance out of range (' + dist.toFixed(1) + ' m: check library fix)');
    }
  } else {
    lines.push(rd.name + ': ' + st);
  }
});
var led = val('led') || 'off';
var ledColor = led === 'red' ? '#f44336' : led === 'green' ? '#4caf50' : led === 'blue' ? '#2196f3' : '#bdbdbd';
s += '<circle cx="' + C + '" cy="' + C + '" r="9" fill="' + ledColor + '" stroke="#424242" stroke-width="2"/>';
s += '</svg>';
var mic = val('mic_state');
if (mic) lines.push('Mic: ' + mic + (val('mic_level') ? ' (level ' + val('mic_level') + ')' : ''));
lines.push('LED: ' + led);
var html = '<div style="display:flex;flex-direction:column;align-items:center;height:100%;gap:6px;padding:4px">';
html += '<div style="flex:1;min-height:0;width:100%;display:flex;justify-content:center">' + s + '</div>';
html += '<div style="font-size:12px;line-height:1.5;color:#424242;width:100%">';
lines.forEach(function (t) { html += '<div>' + t + '</div>'; });
html += '</div></div>';
return html;
